// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(address logFileAddr, uint256 minSumVal) public {
        // Set a distinctive MinSum value via the correctly-behaving setter.
        c.SetMinSum(minSumVal);
        uint256 minSumBefore = c.MinSum();

        // Exercise the unit under test: SetLogFile before Initialized().
        // In M this writes minSumVal target; in P it only updates Log.
        c.SetLogFile(logFileAddr);

        // General rule: SetLogFile must not alter MinSum.
        assertTrue(c.MinSum() == minSumBefore);
    }
}
